import{_ as a,v as e,u as t}from"../virtual/entry.mjs";import{u as o}from"./useCanonical-CM5aTsZw.mjs";import{B as s}from"../routes/renderer.mjs";import"../_/nitro.mjs";import"node:buffer";import"node:timers";import"node:events";import"node:process";import"cloudflare:workers";import"node:fs/promises";import"node:path";import"../_/shared.esm-bundler.mjs";var i=e.defineComponent({__name:"privacy",__ssrInlineRender:!0,setup:a=>(o("/legal/privacy"),t({title:"Privacy Policy",meta:[{name:"description",content:"Privacy Policy for Yannosay Resources."},{property:"og:title",content:"Privacy Policy"}]}),(a,t,o,i)=>{t(`<section${s(e.mergeProps({class:"legal"},i))} data-v-91a1c202><div class="legal__container" data-v-91a1c202><header class="legal__header" data-v-91a1c202><p class="legal__eyebrow" data-v-91a1c202>Legal</p><h1 class="legal__title" data-v-91a1c202>Privacy Policy</h1><p class="legal__updated" data-v-91a1c202>Last updated: 27 September 2026</p></header><article class="prose legal__body" data-v-91a1c202><h2 data-v-91a1c202>Summary</h2><p data-v-91a1c202> Yannosay Resources collects as little as possible. No accounts for downloaders. No analytics. No third-party trackers. No cookies for public visitors. This page explains what is stored and why. </p><h2 data-v-91a1c202>What we store</h2><h3 data-v-91a1c202>Download counts</h3><p data-v-91a1c202> When you request a download, the server increments a counter associated with that resource. The counter records only a number. It does not record your IP address, user agent, or any identifier that could be linked back to you. </p><h3 data-v-91a1c202>Server logs</h3><p data-v-91a1c202> Cloudflare, which hosts this Site, may retain standard request logs for a short period for the purpose of abuse prevention and reliability. These logs are held by Cloudflare under their own privacy policy and are not accessed by Yannosay Productions except in response to a specific incident. </p><h3 data-v-91a1c202>Admin cookies</h3><p data-v-91a1c202> The administrative interface at <code data-v-91a1c202>/admin</code> sets a single HttpOnly session cookie when an administrator signs in. Public visitors never receive this cookie. It is not used for tracking and is deleted on sign-out or after 8 hours of inactivity. </p><h2 data-v-91a1c202>What we do not store</h2><ul data-v-91a1c202><li data-v-91a1c202>No names, email addresses, or postal addresses of visitors.</li><li data-v-91a1c202>No advertising identifiers, tracking pixels, or fingerprinting data.</li><li data-v-91a1c202>No IP addresses associated with download counts.</li><li data-v-91a1c202>No cookies for public visitors.</li><li data-v-91a1c202>No analytics of any kind.</li></ul><h2 data-v-91a1c202>Third parties</h2><p data-v-91a1c202> The Site is served by Cloudflare (Pages, R2, and KV). Cloudflare processes requests on our behalf and is subject to a data processing agreement. We do not send any data to any other third party. </p><h2 data-v-91a1c202>Your rights under GDPR</h2><p data-v-91a1c202> Because we do not associate stored data with individual visitors, there is typically nothing to access, correct, or delete on request. If you believe we hold personal data about you, contact <strong data-v-91a1c202>contact@yannosay.com</strong> and we will investigate. </p><h2 data-v-91a1c202>Children</h2><p data-v-91a1c202> This Site is not directed at children under 13. We do not knowingly collect data from children. </p><h2 data-v-91a1c202>Changes to this policy</h2><p data-v-91a1c202> Material changes will be reflected by a new “Last updated” date at the top of this page. </p><h2 data-v-91a1c202>Contact</h2><p data-v-91a1c202> Questions about this policy should be directed to <strong data-v-91a1c202>contact@yannosay.com</strong>. </p></article></div></section>`)})}),r=i.setup;i.setup=(a,t)=>{const o=e.useSSRContext();return(o.modules||(o.modules=new Set)).add("pages/legal/privacy.vue"),r?r(a,t):void 0};var d=a(i,[["__scopeId","data-v-91a1c202"]]);expor